-- 0002_security_harden: schema changes from the security-harden branch, converted from its
-- SQLite SCHEMA (server/accounts.js), migrateInviteColumns and SECURITY_EVENTS_SCHEMA
-- (server/security-events.js). Only adds columns, an index and tables; nothing is dropped or
-- renamed.
--
-- Conversion rules (same as 0001_initial.sql):
--   * Millisecond timestamps become BIGINT.
--   * Small counters (token counts, alert count) stay INTEGER.
--   * security_events.id AUTOINCREMENT becomes BIGINT GENERATED BY DEFAULT AS IDENTITY, so the
--     SQLite importer can insert the original ids and then setval() the sequence.
--   * security_alerts.seq replaces SQLite's implicit rowid as the insertion-order tie-breaker
--     for alerts created in the same millisecond. It is not part of the imported column set;
--     the importer reads alerts in rowid order, so seq keeps the source order.
--
-- Runs inside a single transaction: no CONCURRENTLY, no non-transactional DDL.

-- invites: single-use links and per-link ids (list and revoke by id).
-- id stays nullable, as in security-harden; existing rows get an id here and insertInvite
-- always supplies one. The unique index allows any number of NULLs.
ALTER TABLE invites
  ADD COLUMN used_at BIGINT,
  ADD COLUMN used_by TEXT REFERENCES users(id),
  ADD COLUMN id TEXT;
UPDATE invites SET id = gen_random_uuid()::text WHERE id IS NULL;
CREATE UNIQUE INDEX invites_id ON invites(id);

-- settings: admin-editable application settings (receipt AI policy).
CREATE TABLE settings (
  key TEXT PRIMARY KEY,
  value TEXT NOT NULL,
  updated_at BIGINT NOT NULL,
  updated_by TEXT NOT NULL
);

-- receipt_ai_usage: one row per OpenAI call. trip_id has no foreign key so usage survives
-- trip deletion.
CREATE TABLE receipt_ai_usage (
  id TEXT PRIMARY KEY,
  at BIGINT NOT NULL,
  user_id TEXT NOT NULL REFERENCES users(id),
  trip_id TEXT NOT NULL,
  model_id TEXT NOT NULL,
  prompt_tokens INTEGER NOT NULL DEFAULT 0,
  completion_tokens INTEGER NOT NULL DEFAULT 0,
  outcome TEXT NOT NULL CHECK (outcome IN ('pending', 'success', 'error', 'timeout'))
);
CREATE INDEX receipt_ai_usage_at ON receipt_ai_usage(at);
CREATE INDEX receipt_ai_usage_user_at ON receipt_ai_usage(user_id, at);

-- security_events: Failed_Login_Events, kept apart from audit.
CREATE TABLE security_events (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  at BIGINT NOT NULL,
  client TEXT NOT NULL,
  username TEXT NOT NULL,
  reason TEXT NOT NULL CHECK (reason IN ('invalid_input', 'rate_limited', 'deleted_account', 'bad_credentials'))
);
CREATE INDEX security_events_at ON security_events(at);
CREATE INDEX security_events_user_at ON security_events(username, at);

-- security_alerts: Security_Alerts created by the Alert_Dispatcher.
CREATE TABLE security_alerts (
  id TEXT PRIMARY KEY,
  at BIGINT NOT NULL,
  kind TEXT NOT NULL CHECK (kind IN ('username', 'global')),
  username TEXT NOT NULL,
  client TEXT NOT NULL,
  count INTEGER NOT NULL,
  window_start BIGINT NOT NULL,
  window_end BIGINT NOT NULL,
  acknowledged_at BIGINT,
  acknowledged_by TEXT,
  seq BIGINT GENERATED ALWAYS AS IDENTITY
);
CREATE INDEX security_alerts_open ON security_alerts(acknowledged_at, at);
